python3 -c "import duckdb, pandas as pd, matplotlib.pyplot as plt; from pathlib import Path; out=Path('out'); days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']; con=duckdb.connect(); d=con.execute(\"SELECT strftime(crash_date, '%A') AS day, count(*) AS crashes FROM read_parquet('data/crashes.parquet') WHERE crash_date >= DATE '2013-01-01' AND crash_date < DATE '2026-01-01' GROUP BY 1\").df(); d=d.set_index('day').reindex(days).reset_index(); d['crashes']=d['crashes'].astype('int64'); total=int(d.crashes.sum()); d['share_percent']=d.crashes/total*100; dates=pd.date_range('2013-01-01','2025-12-31',freq='D'); occ=pd.Series(dates.day_name()).value_counts().reindex(days); d['calendar_dates']=occ.to_numpy(dtype='int64'); d['crashes_per_calendar_date']=d.crashes/d.calendar_dates; d[['day','crashes']].to_csv(out/'values_1.csv',index=False); d[['day','crashes','share_percent']].to_csv(out/'values_2.csv',index=False,float_format='%.6f'); d[['day','crashes','calendar_dates','crashes_per_calendar_date']].to_csv(out/'values_3.csv',index=False,float_format='%.6f'); plt.rcParams.update({'font.size':10,'axes.titlesize':14,'axes.labelsize':11}); specs=[('crashes','Crashes','NYC police-reported crashes by weekday, 2013–2025','out/option_1.png','{:,}'),('share_percent','Share of crashes (%)','Share of NYC police-reported crashes by weekday, 2013–2025','out/option_2.png','{:.1f}%'),('crashes_per_calendar_date','Mean crashes per calendar date','Average crashes per occurrence of each weekday, 2013–2025','out/option_3.png','{:.1f}')];
for col,ylabel,title,path,fmt in specs:
 fig,ax=plt.subplots(figsize=(9,5)); vals=d[col]; bars=ax.bar(d.day,vals,color=['#4C78A8' if x!='Friday' else '#F58518' for x in d.day]); ax.set_title(title,pad=14,weight='bold'); ax.set_ylabel(ylabel); ax.set_xlabel('Day of week'); ax.grid(axis='y',alpha=.25); ax.set_axisbelow(True); ax.spines[['top','right']].set_visible(False); ax.tick_params(axis='x',rotation=20); pad=(vals.max()*.012 if vals.max() else 1); ax.set_ylim(0,vals.max()*1.13); [ax.text(b.get_x()+b.get_width()/2,b.get_height()+pad,fmt.format(v),ha='center',va='bottom',fontsize=9) for b,v in zip(bars,vals)]; fig.tight_layout(); fig.savefig(path,dpi=180,bbox_inches='tight'); plt.close(fig)
print('total',total); print(d.to_string(index=False)); print('calendar dates',int(d.calendar_dates.sum()))"

